 static JsonObject observation(){String window="w",panel="android.widget.LinearLayout@2222",root="android.widget.FrameLayout@1111",target=KIND+"@abcd";JsonArray nodes=new JsonArray();nodes.add(object("id",window+":"+root,"window_id",window,"class","android.widget.FrameLayout","package","com.qinggan.app.setting","present",true,"visible",true,"bridge_version",1));nodes.add(object("id",window+":"+panel,"parent",window+":"+root,"window_id",window,"class","android.widget.LinearLayout","package","com.qinggan.app.setting","present",true,"visible",true,"bridge_version",1));nodes.add(object("id",window+":"+target,"parent",window+":"+panel,"window_id",window,"class",KIND,"package","com.qinggan.app.setting","present",true,"visible",true,"bridge_version",1,"bounds",object("x",500,"y",100,"width",150,"height",70),"clipped_bounds",object("x",500,"y",100,"width",150,"height",70),"layout",object("measured_width",150,"measured_height",70),"text_style",object("text_size_px",28)));JsonArray windows=new JsonArray();windows.add(object("id",window,"package","com.qinggan.app.setting","type",1,"read_complete",true,"node_count",3,"root_id",window+":"+root));JsonArray screens=new JsonArray();screens.add(object("screen","primary","scope","all_attached","status","partial","complete",false,"windows",windows,"nodes",nodes));return object("format","voyemu.ui.v1","profile","profile","session_id","session","boot_id",BOOT,"source_instance","observer","observation_id","new-observation","source_clock_domain","android.uptime","started_uptime_ms","100","completed_uptime_ms","120","screens",screens);}
