 static JsonObject queue(){return object("process","com.qinggan.app.setting","generationId",GEN,"catalogSha256",CAT,"documentGeneration","1","snapshotSha256",SNAP,"frames","D","targetPid","42","targetStarttime","4","endpointEpoch","5");}
 static InstallerLogs.Snapshot baseline(){return new InstallerLogs.Snapshot(BOOT,WRITER,BigInteger.ONE,BigInteger.ONE,Set.of(BigInteger.ONE),Instant.EPOCH,List.of(),List.of(),Path.of("/baseline"));}
 static InstallerLogs.Snapshot snapshot(List<InstallerLogs.Diagnostic> rows,List<InstallerLogs.DaemonEvent> queue){Set<BigInteger> ids=new HashSet<>();int end=rows.stream().mapToInt(r->r.sequence().intValueExact()).max().orElse(2);for(int i=1;i<=end;i++)ids.add(BigInteger.valueOf(i));return new InstallerLogs.Snapshot(BOOT,WRITER,BigInteger.valueOf(end),BigInteger.valueOf(end),ids,Instant.EPOCH.plusSeconds(1),rows,List.of(),Path.of("/current"),queue);}
 static JsonObject read(List<InstallerLogs.Diagnostic> rows,JsonObject q,JsonObject ui)throws Exception{return SettingsOemMeasurements.read(baseline(),snapshot(rows,List.of(new InstallerLogs.DaemonEvent(BigInteger.valueOf(2),"runtime","desired-snapshot-queued",q))),runtime(),ui,"profile","session",BOOT,"en",21);}
 @Test void actualOemActionRoleUsesAuthenticatedPublicationAndLiveObjectNotLegacyComponents()throws Exception {var result=read(rows(),queue(),observation());assertTrue(result.get("viewMetricsVerified").getAsBoolean());assertEquals(KIND+"@abcd",result.getAsJsonArray("rows").get(0).getAsJsonObject().get("viewIdentity").getAsString());assertFalse(result.get("visualAcceptance").getAsBoolean());}
 @Test void wrongEndpointSnapshotRevisionLocaleAndMissingIdentityReject()throws Exception {for(String field:List.of("generationId","catalogSha256","targetPid","targetStarttime","endpointEpoch","snapshotSha256","documentGeneration")){var q=queue();q.addProperty(field,"foreign");assertThrows(IOException.class,()->read(rows(),q,observation()),field);}for(String field:List.of("targetPid","bootId","desiredDocumentGeneration")){var rs=rows();rs.get(1).sourceFields().addProperty(field,"foreign");assertThrows(IOException.class,()->read(rs,queue(),observation()),field);}var rs=rows();rs.remove(1);assertThrows(IOException.class,()->read(rs,queue(),observation()));}
 @Test void objectCollisionUnrelatedRootAndRealMetricClippingReject()throws Exception {for(String mutation:List.of("identity","root","position","clip","glyphs","size")){var rs=rows();switch(mutation){case "identity"->rs.get(1).fields().addProperty("viewIdentity",KIND+"@ffff");case "root"->rs.get(1).fields().addProperty("rootIdentity","android.widget.FrameLayout@9999");case "position"->rs.get(1).fields().addProperty("screenX",501);case "clip"->rs.get(2).fields().addProperty("ellipsis",1);case "glyphs"->rs.get(2).fields().addProperty("caption_px",100);case "size"->rs.get(3).fields().addProperty("textSize",29);}assertThrows(IOException.class,()->read(rs,queue(),observation()),mutation);}}
